const PKG_VER='2.9.97';
const WIZARD_BUILD='neat-island-bold-river';
// Public GitHub repository used by the installed server for online update checks.
// Set these 3 values to your repository before publishing the Wizard.
const ONECLICK_GITHUB_OWNER="etech-symantec";
const ONECLICK_GITHUB_REPO="elk";
const ONECLICK_GITHUB_BRANCH="main";
function githubRepoReady(){return !/^CHANGE_ME_/.test(ONECLICK_GITHUB_OWNER)&&!/^CHANGE_ME_/.test(ONECLICK_GITHUB_REPO)}
function githubRawBase(){return `https://raw.githubusercontent.com/${ONECLICK_GITHUB_OWNER}/${ONECLICK_GITHUB_REPO}/${ONECLICK_GITHUB_BRANCH}`}
function legacyBootstrapCmd(apply=false){
  if(!githubRepoReady())return '먼저 Wizard 상단의 ONECLICK_GITHUB_OWNER / ONECLICK_GITHUB_REPO 값을 실제 public repository로 설정하세요.';
  const repo=`${ONECLICK_GITHUB_OWNER}/${ONECLICK_GITHUB_REPO}`;
  return `curl -fsSL ${githubRawBase()}/bootstrap-update.sh | sudo bash -s -- --repo ${repo} --branch ${ONECLICK_GITHUB_BRANCH}${apply?' --apply':''}`;
}



function utf8B64(s){const b=new TextEncoder().encode(s);let out='';const n=0x8000;for(let i=0;i<b.length;i+=n)out+=String.fromCharCode(...b.subarray(i,i+n));return btoa(out)}
function generateOneClick(opts){
  opts=opts||{};
  syncCurrentFormValues();
  syncDeployFormValues();
  const L=[];
  const q=s=>s.replace(/'/g,"'\\''");
  L.push('#!/usr/bin/env bash');
  L.push('set -Eeuo pipefail');
  L.push("IFS=$'\\n\\t'");
  L.push('');
  L.push('# ELK One-Click Installer v2.9.97');
  L.push('# 이 파일 하나에 elk.env + 설치기 + 보조 스크립트가 모두 포함되어 있습니다.');
  L.push('# PC/Git Bash/WSL에서 일반 권한으로 실행하면 설정된 Ubuntu 서버로 자동 SCP 전송 후 원격 설치합니다.');
  L.push('# Ubuntu 직접 설치: sudo bash elk-oneclick-install-v2.9.97.sh --local-install');
  L.push('# 원격 자동 배포:   bash elk-oneclick-install-v2.9.97.sh --deploy');
  L.push('# 전송만:           bash elk-oneclick-install-v2.9.97.sh --deploy-only');
  L.push('# 검증만(서버):     sudo bash elk-oneclick-install-v2.9.97.sh --validate');
  L.push('# 상태점검(서버):   sudo bash elk-oneclick-install-v2.9.97.sh --check');
  L.push('# 버전확인(서버):   sudo elk-oneclick-version');
  L.push('# 버전비교(서버):   sudo bash elk-oneclick-install-v2.9.97.sh --version-check');
  L.push('# 자동패치(파일):   sudo bash elk-oneclick-install-v2.9.97.sh --auto-patch');
  L.push('# GitHub 확인(서버):   sudo elk-oneclick-update --check');
  L.push('# GitHub 패치(서버):   sudo elk-oneclick-update --apply');
  L.push('');
  L.push('# 색상: --color=always|never|auto (기본 auto: 터미널일 때만), --no-color, 환경변수 ELK_COLOR / NO_COLOR 도 사용할 수 있습니다.');
  L.push('# ---- 화면 색상 도우미 (elk-color.sh 와 같은 내용) ----');
  for(const l of decodeUtf8B64(EMBEDDED_FILES['elk-color.sh']).replace(/\r/g,'').split('\n')){if(!/^#!/.test(l))L.push(l)}
  L.push('# ---- 색상 도우미 끝 ----');
  L.push('');
  L.push('DEPLOY_HOST='+shellQuote(deployValues.host));
  L.push('DEPLOY_USER='+shellQuote(deployValues.user));
  L.push('DEPLOY_SSH_PASSWORD_B64='+shellQuote(utf8B64(opts.paste?'':(deployValues.password||''))));
  L.push('DEPLOY_SUDO_SAME_AS_SSH='+shellQuote(String(deployValues.sudoSame)));
  L.push('DEPLOY_SUDO_PASSWORD_B64='+shellQuote(utf8B64(opts.paste?'':(deployValues.sudoPassword||''))));
  L.push('DEPLOY_SSH_PORT='+shellQuote(deployValues.port));
  L.push('DEPLOY_REMOTE_DIR='+shellQuote(deployValues.remoteDir));
  L.push('DEPLOY_AUTO_INSTALL='+shellQuote(String(deployValues.autoInstall)));
  L.push('DEPLOY_REMOVE_REMOTE_INSTALLER_AFTER='+shellQuote(String(deployValues.removeAfter)));
  L.push("ONECLICK_PAYLOAD_VERSION='2.9.97'");
  L.push("ONECLICK_PAYLOAD_BUILD='steady-tree-quiet-bridge'");
  L.push('ONECLICK_RELEASE_FILE="/etc/elk-auto/oneclick-release.env"');
  L.push('ONECLICK_VERSION_BIN="/usr/local/sbin/elk-oneclick-version"');
  L.push('ONECLICK_UPDATE_BIN="/usr/local/sbin/elk-oneclick-update"');
  L.push('ONECLICK_GITHUB_OWNER="etech-symantec"');
  L.push('ONECLICK_GITHUB_REPO="elk"');
  L.push('ONECLICK_GITHUB_BRANCH='+shellQuote(ONECLICK_GITHUB_BRANCH));
  L.push("ELK_PACKAGE_RESOLVER='v2'");
  L.push('');
  L.push("SELF=\"${BASH_SOURCE[0]:-$0}\"");
  L.push('ARGS=(); for _a in "$@"; do case "$_a" in --color=*) ELK_COLOR="${_a#--color=}"; export ELK_COLOR ;; --no-color) ELK_COLOR=never; export ELK_COLOR ;; *) ARGS+=("$_a") ;; esac; done');
  L.push('set -- "${ARGS[@]+"${ARGS[@]}"}"');
  L.push('elk_color_init');
  L.push("MODE=\"${1:-}\"");
  L.push("REMOTE_UNIT_STATE=\"/run/elk-oneclick-install.unit\"");
  L.push("REMOTE_RUNTIME_STATE=\"/run/elk-oneclick-install.script\"");
  L.push("REMOTE_CONSOLE_LOG=\"/var/log/elk-oneclick-console.log\"");
  L.push("");
  L.push("die(){ elk_say ERROR \"$*\"; exit 1; }");
  L.push("need_cmd(){ command -v \"$1\" >/dev/null 2>&1 || die \"$1 명령을 찾을 수 없습니다.\"; }");
  L.push('release_read(){');
  L.push('  INSTALLED_VERSION=""; INSTALLED_BUILD=""; INSTALLED_AT=""');
  L.push('  if [[ -f "$ONECLICK_RELEASE_FILE" ]]; then');
  L.push('    # shellcheck disable=SC1090');
  L.push('    source "$ONECLICK_RELEASE_FILE" 2>/dev/null || true');
  L.push('    INSTALLED_VERSION="${ONECLICK_VERSION:-${INSTALLED_VERSION:-}}"');
  L.push('    INSTALLED_BUILD="${ONECLICK_BUILD:-${INSTALLED_BUILD:-}}"');
  L.push('    INSTALLED_AT="${ONECLICK_INSTALLED_AT:-${INSTALLED_AT:-}}"');
  L.push('  fi');
  L.push('  if [[ -z "$INSTALLED_VERSION" && -f /var/log/elk-auto-install.log ]]; then');
  L.push('    INSTALLED_VERSION="$(grep -Eo "ELK One-Click Installer v[0-9]+([.][0-9]+)+" /var/log/elk-auto-install.log 2>/dev/null | tail -1 | sed -E "s/.* v//" || true)"');
  L.push('  fi');
  L.push('}');
  L.push('version_cmp(){');
  L.push('  local a="$1" b="$2" top');
  L.push('  [[ "$a" == "$b" ]] && { echo 0; return; }');
  L.push('  top="$(printf "%s\\n%s\\n" "$a" "$b" | sort -V | tail -1)"');
  L.push('  [[ "$top" == "$a" ]] && echo 1 || echo -1');
  L.push('}');
  L.push('show_version_check(){');
  L.push('  release_read');
  L.push('  echo "ELK One-Click 설치 버전 확인"');
  L.push('  echo "  설치 버전 : ${INSTALLED_VERSION:-확인 불가(구버전/메타데이터 없음)}"');
  L.push('  echo "  설치 빌드 : ${INSTALLED_BUILD:-확인 불가}"');
  L.push('  [[ -n "$INSTALLED_AT" ]] && echo "  설치 시각 : $INSTALLED_AT"');
  L.push('  echo "  최신 버전 : $ONECLICK_PAYLOAD_VERSION"');
  L.push('  echo "  최신 빌드 : $ONECLICK_PAYLOAD_BUILD"');
  L.push('  if [[ -z "$INSTALLED_VERSION" ]]; then');
  L.push('    echo "  상태      : 비교 불가 · --auto-patch 실행 시 현재 설정을 보존한 채 최신 버전 메타데이터를 생성합니다."');
  L.push('    return 3');
  L.push('  fi');
  L.push('  local c; c="$(version_cmp "$INSTALLED_VERSION" "$ONECLICK_PAYLOAD_VERSION")"');
  L.push('  if [[ "$c" == 0 && "${INSTALLED_BUILD:-}" == "$ONECLICK_PAYLOAD_BUILD" ]]; then');
  L.push('    echo "  상태      : 최신 버전"');
  L.push('    return 0');
  L.push('  elif [[ "$c" == 1 ]]; then');
  L.push('    echo "  상태      : 설치 버전이 이 설치 파일보다 새 버전입니다. 다운그레이드는 하지 않습니다."');
  L.push('    return 4');
  L.push('  elif [[ "$c" == 0 ]]; then');
  L.push('    echo "  상태      : 같은 버전이지만 빌드가 다릅니다. 패치 가능"');
  L.push('    return 1');
  L.push('  else');
  L.push('    echo "  상태      : 업데이트 필요"');
  L.push('    return 1');
  L.push('  fi');
  L.push('}');
  L.push('write_release(){');
  L.push('  install -d -m 755 "$(dirname "$ONECLICK_RELEASE_FILE")"');
  L.push('  cat > "$ONECLICK_RELEASE_FILE" <<EOF');
  L.push('ONECLICK_VERSION="$ONECLICK_PAYLOAD_VERSION"');
  L.push('ONECLICK_BUILD="$ONECLICK_PAYLOAD_BUILD"');
  L.push('ONECLICK_INSTALLED_AT="$(date -Is)"');
  L.push('EOF');
  L.push('  chmod 644 "$ONECLICK_RELEASE_FILE"');
  L.push("  cat > \"$ONECLICK_VERSION_BIN\" <<'EOF'");
  L.push('#!/usr/bin/env bash');
  L.push('set -u');
  L.push('F="${ELK_ONECLICK_RELEASE_FILE:-/etc/elk-auto/oneclick-release.env}"');
  L.push('if [[ ! -f "$F" ]]; then echo "OneClick 설치 버전 정보를 찾을 수 없습니다: $F" >&2; exit 1; fi');
  L.push('# shellcheck disable=SC1090');
  L.push('source "$F"');
  L.push('echo "ELK One-Click Installer v${ONECLICK_VERSION:-unknown} · build ${ONECLICK_BUILD:-unknown}"');
  L.push('[[ -n "${ONECLICK_INSTALLED_AT:-}" ]] && echo "installed: $ONECLICK_INSTALLED_AT"');
  L.push('EOF');
  L.push('  chmod 755 "$ONECLICK_VERSION_BIN"');
  L.push('}');

  L.push("write_update_tool(){");
  L.push("  local src=\"$WORKDIR/elk-oneclick-update.sh\" tmp=\"${ONECLICK_UPDATE_BIN}.new.$$\"");
  L.push("  [[ -s \"$src\" ]] || die \"업데이터 원본이 설치 패키지에 없습니다: $src\"");
  L.push("  bash -n \"$src\" || die \"업데이터 원본 Bash 문법 오류\"");
  L.push("  grep -q -- \"--apply\" \"$src\" || die \"업데이터 원본에 --apply 모드가 없습니다\"");
  L.push("  grep -q -- \"--full\" \"$src\" || die \"업데이터 원본에 --full 모드가 없습니다\"");
  L.push("  install -d -m 755 \"$(dirname \"$ONECLICK_UPDATE_BIN\")\"");
  L.push("  install -m 755 \"$src\" \"$tmp\" || die \"업데이터 임시 파일 설치 실패\"");
  L.push("  bash -n \"$tmp\" || { rm -f \"$tmp\"; die \"업데이터 임시 파일 검증 실패\"; }");
  L.push("  if [[ -f \"$ONECLICK_UPDATE_BIN\" ]]; then cp -a \"$ONECLICK_UPDATE_BIN\" \"${ONECLICK_UPDATE_BIN}.bak.$(date +%Y%m%d-%H%M%S)\" || { rm -f \"$tmp\"; die \"기존 업데이터 백업 실패\"; }; fi");
  L.push("  mv -f \"$tmp\" \"$ONECLICK_UPDATE_BIN\" || die \"업데이터 교체 실패\"");
  L.push("  elk_say OK \"GitHub 증분 업데이터 설치 완료: $ONECLICK_UPDATE_BIN\"");
  L.push("}");

  // 최초 설치도 --apply와 동일한 런타임 파일 집합으로 시작하도록 한다.
  L.push('sync_install_runtime(){');
  L.push('  local n src dest mode tmp');
  L.push('  elk_say INFO "최초 설치 런타임 도구 동기화 (GitHub --apply 대상)"');
  // GitHub main is the authoritative upgrade tool, while EMBEDDED_FILES is a tested offline fallback.
  // Never replace the embedded file with a failed / empty / syntactically invalid download.
  L.push('  local upgrade_url upgrade_tmp');
  L.push('  upgrade_url="https://raw.githubusercontent.com/etech-symantec/elk/main/_internal/core/elk-stack-upgrade.sh"');
  L.push('  upgrade_tmp="$WORKDIR/elk-stack-upgrade.latest.$$"');
  L.push('  if command -v curl >/dev/null 2>&1 && curl -fsSL --retry 3 --connect-timeout 10 --max-time 40 "$upgrade_url" -o "$upgrade_tmp" && [[ -s "$upgrade_tmp" ]] && bash -n "$upgrade_tmp" && grep -q -- "--upgrade" "$upgrade_tmp" && grep -q -- "--allow-force-stop" "$upgrade_tmp"; then');
  L.push('    mv -f "$upgrade_tmp" "$WORKDIR/elk-stack-upgrade.sh"');
  L.push('    elk_say OK "GitHub 최신 elk-stack-upgrade 확인 완료 (승인형 강제 종료 지원)"');
  L.push('  else');
  L.push('    rm -f "$upgrade_tmp"');
  L.push('    elk_say WARN "GitHub 최신 버전 조회 실패: 설치 파일 내 검증된 업그레이드 도구를 사용합니다."');
  L.push('  fi');

  L.push('  for n in elk-color.sh elk-tls-lib.sh proxysg-lib.sh proxysg-log-filter.conf elk-patch.sh elk-stack-upgrade.sh elk-report.sh elk-report-web.py elk-health-monitor.sh elk-ops.sh log-ingest-manager.sh elk-oneclick-adopt.sh proxysg-log-process.sh check-elk.sh; do');
  L.push('    src="$WORKDIR/$n"; [[ -s "$src" ]] || continue');
  L.push('    case "$n" in');
  L.push('      elk-color.sh|elk-tls-lib.sh|proxysg-lib.sh|proxysg-log-filter.conf|elk-report-web.py) dest="/usr/local/lib/elk-auto/$n" ;;');
  L.push('      check-elk.sh) dest="/usr/local/sbin/elk-check" ;;');
  L.push('      proxysg-log-process.sh) dest="${PROXYSG_PROCESS_SCRIPT:-/usr/local/sbin/proxysg-log-process.sh}" ;;');
  L.push('      elk-patch.sh) dest="/usr/local/sbin/elk-patch" ;;');
  L.push('      elk-stack-upgrade.sh) dest="/usr/local/sbin/elk-stack-upgrade" ;;');
  L.push('      elk-report.sh) dest="/usr/local/sbin/elk-report" ;;');
  L.push('      elk-health-monitor.sh) dest="/usr/local/sbin/elk-health-monitor" ;;');
  L.push('      elk-ops.sh) dest="/usr/local/sbin/elk-ops" ;;');
  L.push('      log-ingest-manager.sh) dest="/usr/local/sbin/log-ingest-manager" ;;');
  L.push('      elk-oneclick-adopt.sh) dest="/usr/local/sbin/elk-oneclick-adopt" ;;');
  L.push('      *) continue ;;');
  L.push('    esac');
  L.push('    case "$n" in *.sh|check-elk.sh) bash -n "$src" || die "초기 도구 문법 오류: $n" ;; esac');
  L.push('    case "$n" in *.conf|elk-color.sh|elk-tls-lib.sh|proxysg-lib.sh|elk-report-web.py) mode=644 ;; *) mode=755 ;; esac');
  L.push('    install -d -m 755 "$(dirname "$dest")"');
  L.push('    if [[ -f "$dest" ]] && cmp -s "$src" "$dest"; then continue; fi');
  L.push('    [[ -f "$dest" ]] && cp -a "$dest" "${dest}.before-initial-sync.$(date +%Y%m%d-%H%M%S)"');
  L.push('    tmp="${dest}.new.$$"; install -m "$mode" "$src" "$tmp" && mv -f "$tmp" "$dest" || die "초기 도구 설치 실패: $n"');
  L.push('    elk_say OK "초기 설치 도구: $n → $dest"');
  L.push('  done');
  L.push('  [[ -x /usr/local/sbin/elk-stack-upgrade ]] || die "ELK 버전 도구가 설치되지 않았습니다."');
  L.push('  [[ -f /usr/local/lib/elk-auto/elk-color.sh ]] || die "색상 도우미가 설치되지 않았습니다."');
  L.push('  bash -n "$ONECLICK_UPDATE_BIN" || die "초기 업데이터 문법 검사 실패"');
  L.push('}');

  L.push('auto_patch(){');
  L.push('  [[ $EUID -eq 0 ]] || die "--auto-patch는 root 권한이 필요합니다. sudo로 실행하세요."');
  L.push('  local env="/etc/elk-auto/elk.env" backup="" c=0');
  L.push('  [[ -f "$env" ]] || die "기존 설치 설정을 찾을 수 없습니다: $env"');
  L.push('  release_read');
  L.push('  if [[ -n "$INSTALLED_VERSION" ]]; then');
  L.push('    c="$(version_cmp "$INSTALLED_VERSION" "$ONECLICK_PAYLOAD_VERSION")"');
  L.push('    if [[ "$c" == 1 ]]; then die "설치된 v$INSTALLED_VERSION 이 현재 payload v$ONECLICK_PAYLOAD_VERSION 보다 새 버전이라 패치를 중단합니다."; fi');
  L.push('    if [[ "$c" == 0 && "${INSTALLED_BUILD:-}" == "$ONECLICK_PAYLOAD_BUILD" ]]; then');
  L.push('      elk_say OK "이미 최신 버전입니다: v$INSTALLED_VERSION · build ${INSTALLED_BUILD:-unknown}"');
  L.push('      return 0');
  L.push('    fi');
  L.push('  else');
  L.push('    elk_say WARN "기존 OneClick 버전 메타데이터가 없습니다. 구버전 설치로 간주하고 최신 payload를 적용합니다."');
  L.push('  fi');
  L.push('  backup="${env}.before-oneclick-${ONECLICK_PAYLOAD_VERSION}-$(date +%Y%m%d-%H%M%S)"');
  L.push('  cp -a "$env" "$backup"');
  L.push('  elk_say INFO "기존 설정 백업: $backup"');
  L.push('  elk_banner neutral "[AUTO PATCH] 기존 설정 검증"');
  L.push('  bash "$WORKDIR/install-elk.sh" "$env" --validate');
  L.push('  elk_banner neutral "[AUTO PATCH] 최신 OneClick 구성 적용"');
  L.push('  bash "$WORKDIR/install-elk.sh" "$env"');
  L.push('  elk_say INFO "서비스 안정화를 위해 5초 대기합니다."');
  L.push('  sleep 5');
  L.push('  run_check');
  L.push('  write_release');
  L.push('  write_update_tool');
  L.push('  elk_say OK "자동 패치 완료: v$ONECLICK_PAYLOAD_VERSION · build $ONECLICK_PAYLOAD_BUILD"');
  L.push('  elk_say INFO "설치 설정은 기존 $env 값을 그대로 사용했습니다."');
  L.push('}');

  L.push("usage(){");
  L.push("  echo \"사용법:\"");
  L.push("  echo \"  bash $0                        # 일반 권한이면 자동 SCP 전송 + 분리 원격 설치\"");
  L.push("  echo \"  bash $0 --deploy               # 명시적 원격 자동 배포\"");
  L.push("  echo \"  bash $0 --deploy-only          # SCP 전송만\"");
  L.push("  echo \"  sudo bash $0 --remote-start    # systemd 독립 작업으로 설치 시작\"");
  L.push("  echo \"  sudo bash $0 --remote-monitor  # 실행 중인 원격 작업 모니터\"");
  L.push("  echo \"  sudo bash $0 --local-install   # 현재 Ubuntu 서버에 직접 설치\"");
  L.push("  echo \"  sudo bash $0 --validate        # 설정 검증만\"");
  L.push("  echo \"  sudo bash $0 --check           # 전체 상태 점검만\"");
  L.push("  echo \"  sudo bash $0 --version-check   # 설치된 OneClick 버전과 이 파일 버전 비교\"");
  L.push("  echo \"  sudo bash $0 --auto-patch      # 설치 설정을 유지하고 최신 payload로 자동 패치\"");
  L.push("}");
  L.push("remote_start(){");
  L.push("  [[ $EUID -eq 0 ]] || die \"--remote-start는 root 권한이 필요합니다.\"");
  L.push("  need_cmd systemd-run");
  L.push("  need_cmd systemctl");
  L.push("  local prev=\"\" active=\"\" sub=\"\" unit runtime_dir runtime_script");
  L.push("  if [[ -s \"$REMOTE_UNIT_STATE\" ]]; then");
  L.push("    prev=\"$(cat \"$REMOTE_UNIT_STATE\" 2>/dev/null || true)\"");
  L.push("    if [[ -n \"$prev\" ]]; then");
  L.push("      active=\"$(systemctl show \"$prev\" -p ActiveState --value 2>/dev/null || true)\"");
  L.push("      sub=\"$(systemctl show \"$prev\" -p SubState --value 2>/dev/null || true)\"");
  L.push("      if [[ \"$active\" =~ ^(active|activating|reloading)$ && \"$sub\" != \"exited\" ]]; then");
  L.push("        elk_say INFO \"이미 실행 중인 설치가 있습니다: $prev ($active/$sub)\"");
  L.push("        elk_say INFO \"새 작업을 만들지 않고 기존 설치를 계속 모니터링합니다.\"");
  L.push("        return 0");
  L.push("      fi");
  L.push("    fi");
  L.push("  fi");
  L.push("  unit=\"elk-oneclick-install-$(date +%Y%m%d%H%M%S)\"");
  L.push("  runtime_dir=\"/root/.elk-auto-installer/runtime\"");
  L.push("  runtime_script=\"$runtime_dir/${unit}.sh\"");
  L.push("  mkdir -p \"$runtime_dir\"");
  L.push("  chmod 700 \"$runtime_dir\"");
  L.push("  cp -f -- \"$SELF\" \"$runtime_script\"");
  L.push("  chmod 600 \"$runtime_script\"");
  L.push("  printf '%s.service\\\\n' \"$unit\" > \"$REMOTE_UNIT_STATE\"");
  L.push("  printf '%s\\\\n' \"$runtime_script\" > \"$REMOTE_RUNTIME_STATE\"");
  L.push("  chmod 600 \"$REMOTE_UNIT_STATE\" \"$REMOTE_RUNTIME_STATE\"");
  L.push("  : > \"$REMOTE_CONSOLE_LOG\"");
  L.push("  chmod 600 \"$REMOTE_CONSOLE_LOG\"");
  L.push("  elk_say INFO \"SSH 세션과 분리된 systemd 설치 작업을 시작합니다.\"");
  L.push("  elk_say INFO \"Unit       : ${unit}.service\"");
  L.push("  elk_say INFO \"Console log: $REMOTE_CONSOLE_LOG\"");
  L.push("  systemd-run --unit=\"$unit\" --no-block --property=Type=exec --property=RemainAfterExit=yes --property=\"StandardOutput=append:$REMOTE_CONSOLE_LOG\" --property=\"StandardError=append:$REMOTE_CONSOLE_LOG\" /usr/bin/env ELK_DETACHED_INSTALL=1 /bin/bash \"$runtime_script\" --local-install");
  L.push("  elk_say OK \"설치 작업이 서버에서 독립적으로 시작되었습니다. SSH가 끊겨도 설치는 계속됩니다.\"");
  L.push("}");
  L.push("elk_paint_new(){ local l; while IFS= read -r l; do elk_paint_line \"$l\"; done < <(sed -n \"$1,${2}p\" \"$REMOTE_CONSOLE_LOG\"); }");
  L.push("remote_monitor(){");
  L.push("  [[ $EUID -eq 0 ]] || die \"--remote-monitor는 root 권한이 필요합니다.\"");
  L.push("  need_cmd systemctl");
  L.push("  [[ -s \"$REMOTE_UNIT_STATE\" ]] || die \"원격 설치 상태 파일이 없습니다: $REMOTE_UNIT_STATE\"");
  L.push("  local unit runtime_script=\"\" last=0 total active sub result status loaded seen=0 started=$SECONDS timeout=14400");
  L.push("  unit=\"$(cat \"$REMOTE_UNIT_STATE\")\"");
  L.push("  [[ -s \"$REMOTE_RUNTIME_STATE\" ]] && runtime_script=\"$(cat \"$REMOTE_RUNTIME_STATE\" 2>/dev/null || true)\"");
  L.push("  elk_banner neutral \"ELK Detached Install Monitor\"");
  L.push("  elk_legend");
  L.push("  elk_say INFO \"Unit : $unit\"");
  L.push("  elk_say INFO \"Log  : $REMOTE_CONSOLE_LOG\"");
  L.push("  elk_say INFO \"SSH 연결이 끊겨도 설치 작업 자체는 서버에서 계속됩니다.\"");
  L.push("  echo");
  L.push("  while true; do");
  L.push("    if [[ -f \"$REMOTE_CONSOLE_LOG\" ]]; then");
  L.push("      total=\"$(wc -l < \"$REMOTE_CONSOLE_LOG\" 2>/dev/null || echo 0)\"");
  L.push("      [[ \"$total\" =~ ^[0-9]+$ ]] || total=0");
  L.push("      if (( total > last )); then");
  L.push("        elk_paint_new \"$((last+1))\" \"$total\"");
  L.push("        last=\"$total\"");
  L.push("      fi");
  L.push("    fi");
  L.push("    loaded=\"$(systemctl show \"$unit\" -p LoadState --value 2>/dev/null || true)\"");
  L.push("    [[ \"$loaded\" == \"loaded\" ]] && seen=1");
  L.push("    if (( SECONDS - started >= timeout )); then elk_say ERROR \"설치 모니터 제한 시간 초과(4시간); 서버 설치는 중단하지 않았습니다.\"; return 124; fi");
  L.push("    active=\"$(systemctl show \"$unit\" -p ActiveState --value 2>/dev/null || true)\"");
  L.push("    sub=\"$(systemctl show \"$unit\" -p SubState --value 2>/dev/null || true)\"");
  L.push("    result=\"$(systemctl show \"$unit\" -p Result --value 2>/dev/null || true)\"");
  L.push("    status=\"$(systemctl show \"$unit\" -p ExecMainStatus --value 2>/dev/null || true)\"");
  L.push("    if (( seen )) && { [[ \"$active\" == \"active\" && \"$sub\" == \"exited\" ]] || [[ \"$active\" == \"failed\" ]] || [[ \"$active\" == \"inactive\" ]]; }; then");
  L.push("      sleep 1");
  L.push("      if [[ -f \"$REMOTE_CONSOLE_LOG\" ]]; then");
  L.push("        total=\"$(wc -l < \"$REMOTE_CONSOLE_LOG\" 2>/dev/null || echo 0)\"");
  L.push("        [[ \"$total\" =~ ^[0-9]+$ ]] || total=0");
  L.push("        if (( total > last )); then");
  L.push("          elk_paint_new \"$((last+1))\" \"$total\"");
  L.push("          last=\"$total\"");
  L.push("        fi");
  L.push("      fi");
  L.push("      result=\"$(systemctl show \"$unit\" -p Result --value 2>/dev/null || true)\"");
  L.push("      status=\"$(systemctl show \"$unit\" -p ExecMainStatus --value 2>/dev/null || true)\"");
  L.push("      [[ \"$status\" =~ ^[0-9]+$ ]] || status=1");
  L.push("      elk_paint_flush");
  L.push("      echo");
  L.push("      if [[ \"$active\" == \"active\" && \"$sub\" == \"exited\" && \"$result\" == \"success\" && \"$status\" == \"0\" && -s /var/log/elk-post-install-check.log && -s /etc/elk-auto/oneclick-release.env ]] && grep -q \'^ONECLICK_VERSION=\' /etc/elk-auto/oneclick-release.env; then");
  L.push("        elk_banner ok \"원격 설치 및 설치 후 전체 상태점검이 정상 완료되었습니다.\" \"설치 로그: /var/log/elk-auto-install.log\" \"점검 로그: /var/log/elk-post-install-check.log\"");
  L.push("        if [[ \"$DEPLOY_REMOVE_REMOTE_INSTALLER_AFTER\" == \"true\" ]]; then");
  L.push("          [[ -n \"$runtime_script\" ]] && rm -f -- \"$runtime_script\" 2>/dev/null || true");
  L.push("          [[ -f \"$SELF\" ]] && rm -f -- \"$SELF\" 2>/dev/null || true");
  L.push("        fi");
  L.push("        systemctl stop \"$unit\" >/dev/null 2>&1 || true");
  L.push("        rm -f \"$REMOTE_UNIT_STATE\" \"$REMOTE_RUNTIME_STATE\" 2>/dev/null || true");
  L.push("        return 0");
  L.push("      fi");
  L.push("      elk_banner fail \"원격 설치가 실패했습니다 (Unit result=$result, exit=$status)\" \"설치 로그: /var/log/elk-auto-install.log\" \"콘솔 로그: $REMOTE_CONSOLE_LOG\" \"다음 조치: 위 [ERROR] 줄과 바로 앞 로그를 확인한 뒤 같은 설치 파일을 다시 실행하세요.\"");
  L.push("      (( status > 0 )) || status=1");
  L.push("      return \"$status\"");
  L.push("    fi");
  L.push("    sleep 2");
  L.push("  done");
  L.push("}");
  L.push("deploy_self(){");
  L.push("  local run_remote=\"${1:-true}\"");
  L.push("  [[ -n \"$DEPLOY_HOST\" ]] || die \"DEPLOY_HOST가 비어 있습니다. Wizard 마지막 단계에서 Ubuntu 서버 IP/호스트를 입력하세요.\"");
  L.push("  [[ -n \"$DEPLOY_USER\" ]] || die \"DEPLOY_USER가 비어 있습니다.\"");
  L.push("  [[ \"$DEPLOY_SSH_PORT\" =~ ^[0-9]+$ ]] || die \"DEPLOY_SSH_PORT는 숫자여야 합니다.\"");
  L.push("  [[ -n \"$DEPLOY_REMOTE_DIR\" ]] || die \"DEPLOY_REMOTE_DIR가 비어 있습니다.\"");
  L.push("  [[ \"$DEPLOY_REMOTE_DIR\" != *\"'\"* ]] || die \"원격 경로에는 작은따옴표를 사용할 수 없습니다.\"");
  L.push("  [[ -f \"$SELF\" ]] || die \"현재 설치 파일을 찾을 수 없습니다: $SELF\"");
  L.push("  need_cmd scp");
  L.push("  need_cmd ssh");
  L.push("  local target=\"${DEPLOY_USER}@${DEPLOY_HOST}\"");
  L.push("  local base remote_file");
  L.push("  base=\"$(basename \"$SELF\")\"");
  L.push("  remote_file=\"${DEPLOY_REMOTE_DIR%/}/$base\"");
  L.push("  elk_banner neutral \"ELK 원격 자동 배포\"");
  L.push("  local cflag=\"--color=never\"; (( ELK_COLOR_ON )) && cflag=\"--color=always\"");
  L.push("  elk_legend");
  L.push("  elk_say INFO \"대상       : $target\"");
  L.push("  elk_say INFO \"SSH Port   : $DEPLOY_SSH_PORT\"");
  L.push("  elk_say INFO \"원격 파일  : $remote_file\"");
  L.push("  elk_say INFO \"1/3 SCP 전송 시작 (필요 시 SSH 비밀번호 입력)\"");
  L.push("  scp -P \"$DEPLOY_SSH_PORT\" \"$SELF\" \"$target:$remote_file\"");
  L.push("  elk_say OK \"SCP 전송 완료\"");
  L.push("  if [[ \"$run_remote\" != \"true\" || \"$DEPLOY_AUTO_INSTALL\" != \"true\" ]]; then");
  L.push("    elk_say INFO \"전송만 완료했습니다. Ubuntu에서: sudo bash $remote_file --local-install\"");
  L.push("    return 0");
  L.push("  fi");
  L.push("  elk_say INFO \"2/3 서버 독립 설치 작업 시작 (필요 시 SSH/sudo 비밀번호 입력)\"");
  L.push("  ssh -tt -o ServerAliveInterval=15 -o ServerAliveCountMax=12 -p \"$DEPLOY_SSH_PORT\" \"$target\" \"sudo bash '$remote_file' --remote-start $cflag\"");
  L.push("  elk_say INFO \"3/3 원격 설치 진행상황 모니터링\"");
  L.push("  ssh -tt -o ServerAliveInterval=15 -o ServerAliveCountMax=12 -p \"$DEPLOY_SSH_PORT\" \"$target\" \"sudo bash '$remote_file' --remote-monitor $cflag\"");
  L.push("}");
  L.push("if [[ \"$MODE\" == \"--deploy\" || \"$MODE\" == \"deploy\" ]]; then deploy_self true; exit $?; fi");
  L.push("if [[ \"$MODE\" == \"--deploy-only\" || \"$MODE\" == \"deploy-only\" ]]; then deploy_self false; exit $?; fi");
  L.push("if [[ -z \"$MODE\" && $EUID -ne 0 ]]; then deploy_self true; exit $?; fi");
  L.push("[[ $EUID -eq 0 ]] || { usage; die \"로컬 설치/점검은 root 권한이 필요합니다. sudo 또는 --deploy를 사용하세요.\"; }");
  L.push("[[ -f \"$SELF\" ]] && chmod 600 \"$SELF\" 2>/dev/null || true");
  L.push("if [[ \"$MODE\" == \"--remote-start\" || \"$MODE\" == \"remote-start\" ]]; then remote_start; exit $?; fi");
  L.push("if [[ \"$MODE\" == \"--remote-monitor\" || \"$MODE\" == \"--remote-status\" || \"$MODE\" == \"remote-monitor\" || \"$MODE\" == \"remote-status\" ]]; then remote_monitor; exit $?; fi");
  L.push("[[ \"$MODE\" == \"--local-install\" || \"$MODE\" == \"local-install\" ]] && MODE=\"install\"");
  L.push("[[ -z \"$MODE\" ]] && MODE=\"install\"");
  L.push('WORKDIR="$(mktemp -d /tmp/elk-oneclick.XXXXXX)"');
  L.push('cleanup(){ rm -rf "$WORKDIR"; }');
  L.push('trap cleanup EXIT');
  L.push('elk_say INFO "ELK One-Click Installer v2.9.97"');
  L.push('elk_say INFO "임시 작업경로: $WORKDIR"');
  L.push('');
  const env64=utf8B64(generateEnv());
  L.push("cat <<'__ELK_ENV_B64__' | base64 -d > \"$WORKDIR/elk.env\"");
  L.push(env64); L.push('__ELK_ENV_B64__');
  L.push('chmod 600 "$WORKDIR/elk.env"');
  const EF=effectiveEmbedded();
  for(const [name,b64] of Object.entries(EF.files)){
    const tag='__ELK_'+name.replace(/[^A-Za-z0-9]/g,'_').toUpperCase()+'_B64__',gzb=opts.gz&&opts.gz[name];
    L.push("cat <<'"+tag+"' | base64 -d "+(gzb?'| gunzip -c ':'')+'> "$WORKDIR/'+name+'"');
    L.push(gzb||b64); L.push(tag);
    L.push('chmod '+EF.modes[name]+' "$WORKDIR/'+name+'"');
  }
  L.push('');
  L.push('run_validate(){');
  L.push('  echo');
  L.push('  elk_banner neutral "[1/3] 설치 설정 자동 검증"');
  L.push('  bash "$WORKDIR/install-elk.sh" "$WORKDIR/elk.env" --validate');
  L.push('}');
  L.push('run_check(){');
  L.push('  local env="/etc/elk-auto/elk.env"');
  L.push('  [[ -f "$env" ]] || env="$WORKDIR/elk.env"');
  L.push('  echo');
  L.push('  elk_banner neutral "[3/3] 설치 후 전체 상태 자동 점검"');
  L.push('  set +e');
  L.push('  bash "$WORKDIR/check-elk.sh" "$env" 2>&1 | tee /var/log/elk-post-install-check.log | elk_paint_stream');
  L.push('  local rc=${PIPESTATUS[0]}');
  L.push('  set -e');
  L.push('  if (( rc == 0 )); then');
  L.push('    elk_say OK "설치 및 전체 상태 점검이 완료되었습니다."');
  L.push('    elk_say INFO "상태점검 로그: /var/log/elk-post-install-check.log"');
  L.push('  else');
  L.push('    elk_say ERROR "설치는 끝났지만 상태 점검 실패 항목이 있습니다."');
  L.push('    elk_say INFO "설치 로그: /var/log/elk-auto-install.log" >&2');
  L.push('    elk_say INFO "상태점검 로그: /var/log/elk-post-install-check.log" >&2');
  L.push('    return "$rc"');
  L.push('  fi');
  L.push('}');
  L.push('');
  L.push('case "$MODE" in');
  L.push('  --validate|validate) run_validate ;;');
  L.push('  --check|check) run_check ;;');
  L.push('  --version|version|--version-check|version-check) set +e; show_version_check; _vrc=$?; set -e; exit "$_vrc" ;;');
  L.push('  --auto-patch|auto-patch) auto_patch ;;');
  L.push('  install)');
  L.push('    run_validate');
  L.push('    echo');
  L.push('    elk_banner neutral "[2/3] ELK / FTP / 선택 구성요소 자동 설치"');
  L.push('    bash "$WORKDIR/install-elk.sh" "$WORKDIR/elk.env"');
  L.push('    elk_say INFO "서비스 안정화를 위해 5초 대기합니다."');
  L.push('    sleep 5');
  L.push('    run_check');
  L.push('    write_release');
  L.push('    write_update_tool');
    L.push('    sync_install_runtime');
  L.push('    elk_say INFO "OneClick 버전 기록: $ONECLICK_PAYLOAD_VERSION · build $ONECLICK_PAYLOAD_BUILD"');
  L.push('    [[ -x "$ONECLICK_UPDATE_BIN" ]] && elk_say INFO "GitHub 업데이트: sudo elk-oneclick-update --check / --apply"');
  L.push('    if [[ "$DEPLOY_REMOVE_REMOTE_INSTALLER_AFTER" == "true" && "${ELK_DETACHED_INSTALL:-0}" != "1" && -f "$SELF" ]]; then');
  L.push('      elk_say INFO "설치 성공: 단일 설치 파일을 삭제합니다: $SELF"');
  L.push('      rm -f -- "$SELF" || true');
  L.push('    fi');
  L.push('    ;;');
  L.push('  *)');
  L.push('    usage');
  L.push('    exit 2');
  L.push('    ;;');
  L.push('esac');
  L.push('');
  return L.join('\n')+'\n';
}

const VM=Object.fromEntries(DATA.vars.map(v=>[v.key,v]));let values={};let mode='simple',step=1,query='';let expandedCards=new Set();let expandedDeployCards=new Set();let deployValues={};
function reset(){values={};for(const v of DATA.vars)values[v.key]=v.default;deployValues={host:'172.16.70.208',user:'etech',password:'',sudoSame:true,sudoPassword:'',port:'22',remoteDir:'/home/etech',autoInstall:true,removeAfter:true}}reset();
const bool=v=>String(v).toLowerCase()==='true';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

// ---- 관리자 기본값 파일(wizard-defaults.js) 적용 -------------------------------------------
// window.ELK_DEFAULTS = { values:{KEY:"값"}, deploy:{host:"..",...} }  (파일이 없으면 내장 기본값 사용)

// ---- 기본값 표시용: 처음 열었을 때(관리자 기본값 포함)의 값을 기억해 각 카드에 "기본값: …"으로 보여 줍니다.
let INITIAL_VALUES={},INITIAL_DEPLOY={};
function defLabel(k){const d=INITIAL_VALUES[k];if(d===undefined)return '';if(isBoolVar(k))return bool(d)?'사용':'사용 안 함';return d===''?'비어 있음':String(d)}
function defLine(k){const d=INITIAL_VALUES[k];if(d===undefined)return '';const chg=String(values[k]??'')!==String(d);return `<div class="defline">기본값: <b>${esc(defLabel(k))}</b><span class="chg" ${chg?'':'hidden'}>● 기본값에서 변경됨</span></div>`}
function deployDefLine(k){if(!(k in INITIAL_DEPLOY))return '';const d=INITIAL_DEPLOY[k],sec=DEPLOY_META[k]&&DEPLOY_META[k].secret;const t=typeof d==='boolean'?(d?'사용':'사용 안 함'):(d===''?'비어 있음':String(d));const chg=!sec&&deployValues[k]!==d;return `<div class="defline">기본값: <b>${esc(t)}</b><span class="chg" ${chg?'':'hidden'}>● 기본값에서 변경됨</span></div>`}
function segControl(attr,key,on,defOn){
  const b=(val,txt)=>`<button type="button" class="segbtn ${val?'on':'off'} ${on===val?'sel':''}" data-seg-for="${key}" data-seg-v="${val}" aria-pressed="${on===val}">${txt}${defOn===val?'<i>기본</i>':''}</button>`;
  return `<div class="seg" role="group"><input ${attr}="${key}" type="checkbox" class="segchk" ${on?'checked':''}>${b(true,'사용')}${b(false,'사용 안 함')}</div>`
}
function syncSeg(key,on){document.querySelectorAll(`[data-seg-for="${key}"]`).forEach(b=>{const sel=(b.dataset.segV==='true')===on;b.classList.toggle('sel',sel);b.setAttribute('aria-pressed',String(sel))})}


// ---- ProxySG MAIN/SSL 로그 포맷(ELFF) -> Logstash csv columns  (설치기 install-elk.sh의 elff_columns 와 같은 규칙) ----

// ---- ProxySG Cloud 로그(선택) 보조 --------------------------------------------------------------
function isCloudKey(k){return /^PROXYSG_CLOUD_/.test(k)&&k!=='PROXYSG_CLOUD_ENABLED'}
const cloudOn=()=>bool(values.PROXYSG_CLOUD_ENABLED);
var TC='<span class="ftag tcloud">Cloud</span>';
function logTypesPanel(){
  const v=values,flow=bool(v.PROXYSG_FLOW_ENABLED),cl=cloudOn();
  const cell=(tag,name,type,pre,on,extra)=>`<div class="ltcell ${on?'on':'off'}"><div class="lthead">${tag}<span class="ltstate ${on?'on':'off'}">${on?'사용':'비활성'}</span></div><div class="ltmeta">${name}</div><div class="ltmeta">Logstash type ${cd(type)} · 인덱스 ${cd(pre+'-*')}</div>${extra||''}</div>`;
  const why=flow?'':'<div class="ltwhy">로그 처리 스크립트가 사용 안 함이라 처리되지 않습니다.</div>';
  const fw=cl?'<div class="ltfwalert"><b>⚠ 외부 방화벽 허용이 필요합니다.</b><br>Cloud API 로그 다운로드를 위해 ELK 서버에서 아래 목적지로 HTTPS 아웃바운드 통신이 가능해야 합니다.<br><code>portal.threatpulse.com · TCP/443</code></div>':'';
  const sw=`<div class="ltsw"><span>Cloud 로그 처리</span>${segControl('data-k','PROXYSG_CLOUD_ENABLED',cl,bool(INITIAL_VALUES.PROXYSG_CLOUD_ENABLED!==undefined?INITIAL_VALUES.PROXYSG_CLOUD_ENABLED:'false'))}</div>${fw}`+(cl&&!flow?'<div class="ltwhy">스크립트가 꺼져 있어 수신 폴더 복사는 자동 실행되지 않습니다.</div>':'')+(cl?'':'<div class="ltwhy">현재 사용 안 함 — 아래 Cloud 항목(회색)은 적용되지 않습니다.</div>');
  return `<section class="ltpanel"><div class="lthead2"><b>처리할 로그 종류</b><small>MAIN·SSL은 로그 처리 스크립트를 사용하면 항상 처리하고, Cloud는 선택 사항입니다. (기본: 사용 안 함)</small></div><div class="ltgrid">${cell(TM,'ProxySG MAIN(HTTP) 로그','edge-http',v.PROXYSG_MAIN_INDEX_PREFIX,flow,why)}${cell(TS,'ProxySG SSL(HTTPS) 로그','edge-https',v.PROXYSG_SSL_INDEX_PREFIX,flow,why)}${cell(TC,'ProxySG Cloud 로그','cloud',v.PROXYSG_CLOUD_INDEX_PREFIX,cl,sw)}</div>
</section>`
}

