function inspectCtx(){
  const v=values,sv=(k,d)=>String(v[k]===undefined||v[k]===''?d:v[k]),tf=k=>bool(v[k]);
  const flow=tf('PROXYSG_FLOW_ENABLED'),cloud=flow&&tf('PROXYSG_CLOUD_ENABLED');
  const defs=[['MAIN','MAIN'],['SSL','SSL']].concat(cloud?[['Cloud','CLOUD']]:[]);
  const T=flow?defs.map(([nm,K])=>({nm,src:sv('PROXYSG_'+K+'_SOURCE_DIR',''),prc:sv('PROXYSG_'+K+'_PROCESS_DIR',''),bak:sv('PROXYSG_'+K+'_BACKUP_DIR',''),pfx:sv('PROXYSG_'+K+'_INDEX_PREFIX','')})):[];
  const pfxs=flow?T.map(t=>t.pfx):[sv('INDEX_PREFIX','network-log')];
  const sec=tf('ES_SECURITY_ENABLED'),tls=v.ES_HTTP_TLS_ENABLED===undefined?true:tf('ES_HTTP_TLS_ENABLED');
  const svcs=['elasticsearch'].concat(tf('INSTALL_KIBANA')?['kibana']:[],tf('INSTALL_LOGSTASH')?['logstash']:[],tf('INSTALL_NGINX')?['nginx']:[],tf('INSTALL_FTP_SERVER')?['vsftpd']:[]);
  const certs=['/etc/elasticsearch/certs/http_ca.crt'].concat(tf('INSTALL_NGINX')?[sv('NGINX_TLS_CERT_FILE','/etc/ssl/certs/kibana-selfsigned.crt')]:[]);
  return {flow,cloud,T,pfxs,sec,tls,port:sv('ES_HTTP_PORT','9200'),user:sv('ELASTIC_USERNAME','elastic'),state:sv('STATE_DIR','/root/.elk-auto-installer'),svcs,certs,
    esdata:sv('ES_PATH_DATA','/var/lib/elasticsearch'),plog:sv('PROXYSG_PROCESS_LOG','/var/log/elk-proxysg-log-process.log'),policy:flow?sv('PROXYSG_ILM_POLICY_NAME','proxy-retention-policy'):sv('ILM_POLICY_NAME',sv('INDEX_PREFIX','network-log')+'-ilm'),
    ftp:tf('INSTALL_FTP_SERVER'),ftpUser:sv('FTP_USER','elkftp'),ftpPort:sv('FTP_LISTEN_PORT','21')}
}
function inspectFill(tpl,map){let s=tpl;for(const k of Object.keys(map))s=s.split('@'+k+'@').join(map[k]);return s}
function inspectPre(c){
  const map={SECRETS:c.state+'/secrets.env',CA:'/etc/elasticsearch/certs/http_ca.crt',USER:c.user,BASE:(c.tls?'https':'http')+'://127.0.0.1:'+c.port};
  return inspectFill(INSPECT_T[c.sec?(c.tls?'pre_tls':'pre_auth'):(c.tls?'pre_tlsopen':'pre_open')],map)
}
// 이 설정에서 의미가 없는 명령은 빈 문자열(페이지에는 "해당 없음" 안내가 나온다)
const INSPECT_NA={disk_logs:'flow',last_files:'flow',backlog:'flow',proc_err:'flow',ftp:'ftp'};
const INSPECT_NA_TEXT={flow:'ProxySG 로그 처리 스크립트를 쓰지 않는 설정이라 해당 없습니다.',ftp:'FTP 서버를 설치하지 않는 설정이라 해당 없습니다.'};
function inspectApplies(id){const c=inspectCtx(),n=INSPECT_NA[id];return !n||(n==='flow'?c.flow:c.ftp)}
function inspectCmd(id){
  const c=inspectCtx(),q=s=>'"'+s+'"';
  if(!inspectApplies(id))return '';
  const list=a=>a.map(q).join(' ');
  const map={PRE:inspectPre(c),POST:INSPECT_T.post,PFXS:c.pfxs.join(' '),SERVICES:c.svcs.join(' '),ESDATA:c.esdata,PLOG:q(c.plog),POLICY:c.policy,CERTS:list(c.certs),FTPUSER:c.ftpUser,FTPPORT:c.ftpPort,DFPATHS:''};
  if(c.flow){
    map.LOGDIRS=list(c.T.reduce((a,t)=>a.concat([t.nm+' SOURCE '+t.src,t.nm+' PROCESS '+t.prc,t.nm+' BACKUP '+t.bak]),[]));
    map.PRCDIRS=list(c.T.map(t=>t.nm+' '+t.prc));
    map.LASTDIRS=list(c.T.map(t=>t.nm+' '+[t.src,t.prc,t.bak].join(' ')));
    const dirs=[];for(const t of c.T)for(const d of [t.src,t.prc,t.bak])if(d&&!dirs.includes(d))dirs.push(d);map.DFPATHS=dirs.join(' ')
  }
  return inspectFill(INSPECT_T[id],map)
}
