function inspectRow(r){
  const [g,id,title,why,ok]=r,cmd=inspectCmd(id);
  const head=`<tr class="irow" data-irow="${id}"><td class="ic1">${esc(title)}</td><td class="ic2">${esc(why)}</td><td class="ic3">${esc(ok)}</td>`;
  if(!cmd)return head+`<td class="ic4"><div class="inote">${esc(INSPECT_NA_TEXT[INSPECT_NA[id]]||'해당 없음')}</div></td></tr>`;
  return head+`<td class="ic4"><div class="icmdline"><div class="icmdone" id="icmd1-${id}" title="${esc(cmd)}">${esc(cmd)}</div><div class="icmdfold" hidden>아래에 펼쳐짐 ▼</div><button type="button" class="ubtn mini" data-icopy="${id}">복사</button><button type="button" class="ubtn mini ghostbtn" data-iexp="${id}" aria-expanded="false" hidden>펼치기</button></div><span class="icopystate" data-istate="${id}"></span></td></tr>`+
   `<tr class="irowx" data-icmdrow="${id}" hidden><td class="icmdfull" colspan="4"><div class="icmdwrap"><pre class="icmd" id="icmd-${id}">${esc(cmd)}</pre></div></td></tr>`
}
// 명령은 기본적으로 오른쪽 30% 칸에 한 줄로 접혀 보이고, 칸보다 길면 "펼치기" 버튼이 나온다.
// 펼치면 그 칸의 명령 입력줄은 아랫줄(항목 전체 폭)로 옮겨 전체가 보인다. (줄 길이는 실제 화면 폭으로 판단하고, 창 크기가 바뀌면 다시 판단한다)
function inspectFitCmds(){
  document.querySelectorAll('.icmdone').forEach(el=>{
    const id=el.id.replace('icmd1-',''),btn=document.querySelector(`[data-iexp="${id}"]`);if(!btn)return;
    const row=document.querySelector(`tr[data-icmdrow="${id}"]`);
    if(row&&!row.hidden){btn.hidden=false;return}
    const measured=el.clientWidth>0;
    btn.hidden=!(measured?el.scrollWidth>el.clientWidth+1:el.textContent.length>32)
  })
}
function inspectToggleRow(id,open){
  const row=document.querySelector(`tr[data-icmdrow="${id}"]`),one=document.getElementById('icmd1-'+id),fold=one&&one.parentNode.querySelector('.icmdfold'),btn=document.querySelector(`[data-iexp="${id}"]`);
  if(!row||!one||!btn)return;
  row.hidden=!open;one.hidden=open;fold.hidden=!open;
  btn.textContent=open?'접기':'펼치기';btn.setAttribute('aria-expanded',open?'true':'false');btn.hidden=false;
  if(!open)inspectFitCmds()
}
function inspectReportArgs(){
  const all=INSPECT_SECTIONS.map(x=>x[0]),sel=all.filter(k=>INSPECT_SECS.has(k));
  let a='';if(sel.length&&sel.length<all.length)a+=' --only '+sel.join(',');
  if(INSPECT_STALE!==36)a+=' --stale-hours '+INSPECT_STALE;
  if(INSPECT_NOCOLOR)a+=' --no-color';
  return a
}
function inspectShortCmd(){return 'sudo elk-report'+inspectReportArgs()+'\n'}
// 서버 터미널에 한 번에 붙여넣는 명령: 압축된 도구를 임시 파일로 풀고 실행한다. 읽기 전용이며 끝나면 스스로 삭제.
function inspectPasteBlock(){
  const gz=PATCH_GZ['elk-report.sh']||'',L=[];for(let i=0;i<gz.length;i+=76)L.push(gz.slice(i,i+76));
  return 'F=$(mktemp /tmp/elk-report.XXXXXX.sh); base64 -d <<\'ELK_REPORT_B64\' | gunzip -c > "$F"\n'+L.join('\n')+'\nELK_REPORT_B64\nsudo bash "$F" --self-delete'+inspectReportArgs()+'\n'
}
