  for(const k of ['ES_HTTP_PORT','KIBANA_SERVER_PORT'].concat(bool(values.ELK_REPORT_WEB_ENABLED)?['ELK_REPORT_WEB_PORT']:[])){const n=Number(values[k]);if(!Number.isInteger(n)||n<1||n>65535)add(k,`${VM[k]?.label||k}는 1~65535 범위여야 합니다.`)}
  if(bool(values.INSTALL_FTP_SERVER)){const n=Number(values.FTP_LISTEN_PORT);if(!Number.isInteger(n)||n<1||n>65535)add('FTP_LISTEN_PORT','FTP Listen Port는 1~65535 범위여야 합니다.');if(!String(values.FTP_USER||'').trim())add('FTP_USER','FTP 계정이 비어 있습니다.');}
  if(bool(values.KIBANA_CREATE_INITIAL_USER)){if(!String(values.KIBANA_INITIAL_USER_NAME||'').trim())add('KIBANA_INITIAL_USER_NAME','Kibana 초기 사용자 ID를 입력하십시오.');if(!String(values.KIBANA_INITIAL_USER_ROLES||'').trim())add('KIBANA_INITIAL_USER_ROLES','Kibana 초기 사용자 Role을 입력하십시오.');}
  if(!hiddenKey('KIBANA_SESSION_IDLE_TIMEOUT')&&String(values.KIBANA_SESSION_IDLE_TIMEOUT||'').trim()&&!/^[0-9]+(ms|s|m|h|d|w|M|Y)$/.test(String(values.KIBANA_SESSION_IDLE_TIMEOUT).trim()))add('KIBANA_SESSION_IDLE_TIMEOUT','로그인 세션 유휴 만료는 30m, 8h, 7d 처럼 숫자+단위(ms,s,m,h,d,w,M,Y)로 입력하거나 비워두십시오.');
  if(bool(values.ILM_DELETE_ENABLED)&&!/^[0-9]+(ms|s|m|h|d|w)$/.test(String(values.ILM_DELETE_MIN_AGE)))add('ILM_DELETE_MIN_AGE','ILM 보존기간 형식을 확인하십시오. 예: 90d');
  if(bool(values.INSTALL_NGINX)&&values.NGINX_TLS_MODE==='existing'){if(!String(values.NGINX_TLS_CERT_FILE||'').startsWith('/'))add('NGINX_TLS_CERT_FILE','기존 인증서 파일은 절대경로여야 합니다.');if(!String(values.NGINX_TLS_KEY_FILE||'').startsWith('/'))add('NGINX_TLS_KEY_FILE','기존 Private Key 파일은 절대경로여야 합니다.');}
  if(proxysgFormatsRelevant()){for(const [k,lb] of [['PROXYSG_MAIN_LOG_FORMAT','MAIN 로그 포맷'],['PROXYSG_SSL_LOG_FORMAT','SSL 로그 포맷']].concat(cloudOn()?[['PROXYSG_CLOUD_LOG_FORMAT','Cloud 로그 포맷']]:[])){const t=String(values[k]||'');if(!t.trim())add(k,`${lb}을 입력하세요. (ProxySG 로그의 #Fields 순서)`);else if(!/^[A-Za-z0-9_.:()\s-]+$/.test(t))add(k,`${lb}에 허용되지 않는 문자가 있습니다. (영문/숫자, - _ . : ( ) 와 공백만 사용)`)}}
