  if(bool(values.ELK_REPORT_WEB_ENABLED)){for(const k of ['ELK_REPORT_HTML_DIR','ELK_REPORT_HTML_FILE']){if(!String(values[k]||'').startsWith('/'))add(k,`${VM[k].label}는 / 로 시작하는 절대경로여야 합니다.`)}if(!String(values.ELK_REPORT_WEB_HOST||'').trim())add('ELK_REPORT_WEB_HOST','점검 웹 Listen 주소가 비어 있습니다.');}
